// Master Event Classifier
const eventType = $input.first().json.event_type || 'unknown';
const eventData = $input.first().json;

// Determine routing
let route = 'unknown';
let priority = 'normal';
let context = {};

if (eventType === 'file_upload') {
  route = 'document_ingestion';

  // Check for transition context
  if (eventData.transition_id) {
    priority = eventData.transition_type === 'major' ? 'critical' : 'high';
    context.transition = true;
  }

  // Check for offboarding source
  if (eventData.source === 'offboarding') {
    priority = 'high';
    context.offboarding_sourced = true;
  }

} else if (eventType === 'message' || eventType === 'communication') {
  route = 'message_processing';
  priority = 'normal';

  // Check user context
  if (eventData.user_status === 'onboarding') {
    context.onboarding_user = true;
  } else if (eventData.user_status === 'offboarding') {
    context.offboarding_user = true;
  }

} else if (eventType === 'user_created') {
  route = 'user_onboarding';
  priority = 'high';

} else if (eventType === 'user_offboarding') {
  route = 'user_offboarding';
  priority = 'high';

} else if (eventType === 'role_change') {
  route = 'personnel_transition';
  priority = 'high';

} else if (eventType === 'transition_initiated') {
  route = 'transition_management';
  priority = eventData.transition_type === 'major' ? 'critical' : 'high';

} else if (eventType === 'learning_request') {
  route = 'user_requested_learning';
  priority = 'normal';

} else if (eventType === 'search_query') {
  route = 'search_retrieval';
  priority = 'normal';

} else if (eventType === 'batch_processing') {
  route = 'batch_ingestion';
  priority = 'low';
}

return [{
  json: {
    ...eventData,
    routing: {
      route: route,
      priority: priority,
      context: context,
      timestamp: new Date().toISOString()
    }
  }
}];

// Extract file metadata and calculate hash
const crypto = require('crypto');
const fileData = $input.first().json;

// Read file content
const fileContent = await window.fs.readFile(fileData.file_path);
const fileHash = crypto.createHash('sha256').update(fileContent).digest('hex');

return [{
  json: {
    file_id: `file-${Date.now()}`,
    file_path: fileData.file_path,
    file_name: fileData.file_name,
    file_size: fileContent.length,
    file_hash: fileHash,
    modified_date: fileData.modified_date || new Date().toISOString(),
    content: fileContent.toString('utf8'),
    ingestion_date: new Date().toISOString(),
    priority: fileData.priority || 'normal',
    transition_context: fileData.transition_id || null,
    source: fileData.source || 'standard'
  }
}];

