// Parse version info and merge with document data
const response = $input.first().json;
const versionInfo = JSON.parse(response.content[0].text);

const previousData = $input.item(1).json; // Get data from previous node

return [{
  json: {
    ...previousData,
    version_info: versionInfo,
    version: versionInfo.version || null,
    publish_date: versionInfo.publish_date || previousData.modified_date,
    author: versionInfo.author || 'unknown'
  }
}];

// Determine currency status
const currentDoc = $input.first().json;
const existingDocs = $input.item(1).json.documents || [];

let status = 'current';
let superseded_by = null;
let supersedes = null;

if (existingDocs.length > 0) {
  const latest = existingDocs[0];

  // Compare versions if both have version numbers
  if (currentDoc.version && latest.version) {
    const currentVer = parseFloat(currentDoc.version.replace(/[^0-9.]/g, ''));
    const latestVer = parseFloat(latest.version.replace(/[^0-9.]/g, ''));

    if (currentVer < latestVer) {
      status = 'superseded';
      superseded_by = latest.doc_id;
    } else if (currentVer > latestVer) {
      status = 'current';
      supersedes = latest.doc_id;
      // Mark old doc as superseded
    }
  } else {
    // Compare by date
    const currentDate = new Date(currentDoc.publish_date);
    const latestDate = new Date(latest.publish_date);

    if (currentDate < latestDate) {
      status = 'superseded';
      superseded_by = latest.doc_id;
    } else {
      status = 'current';
      supersedes = latest.doc_id;
    }
  }
}

// Check for messaging overrides
const overrideCheck = await $input.first().getNode('check-overrides').execute();

if (overrideCheck && overrideCheck.length > 0) {
  status = 'overridden';
  currentDoc.overridden_by = overrideCheck.map(o => o.message_id);
}

return [{
  json: {
    ...currentDoc,
    currency_status: status,
    superseded_by: superseded_by,
    supersedes: supersedes
  }
}];

