// Combine and rank results from multiple search methods
const vectorResults = $input.item(0).json.matches || [];
const keywordResults = $input.item(1).json.documents || [];
const graphResults = $input.item(2).json.results || [];
const userData = $input.item(3).json;

// Combine and deduplicate by chunk_id
const resultsMap = new Map();

vectorResults.forEach(r => {
  resultsMap.set(r.id, {
    chunk_id: r.id,
    score: r.score * 0.5, // Weight vector search
    source: 'vector',
    metadata: r.metadata
  });
});

keywordResults.forEach(r => {
  const existing = resultsMap.get(r.chunk_id);
  if (existing) {
    existing.score += 0.3; // Boost if also found in keyword
    existing.source += '+keyword';
  } else {
    resultsMap.set(r.chunk_id, {
      chunk_id: r.chunk_id,
      score: 0.3,
      source: 'keyword',
      metadata: r
    });
  }
});

graphResults.forEach(r => {
  const existing = resultsMap.get(r.chunk_id);
  if (existing) {
    existing.score += 0.2; // Boost if connected in graph
    existing.source += '+graph';
  }
});

// Sort by score
const rankedResults = Array.from(resultsMap.values())
  .sort((a, b) => b.score - a.score)
  .slice(0, 5); // Top 5

return [{
  json: {
    query: userData.query,
    user_context: userData,
    ranked_chunks: rankedResults
  }
}];

// Process chunks and determine context needs
const chunks = $input.first().json.chunks || [];
const searchData = $input.item(1).json;

const processedChunks = chunks.map(chunk => {
  const needsContext = chunk.standalone_score < 0.7;

  return {
    ...chunk,
    needs_context: needsContext,
    context_window_size: needsContext ? (chunk.ideal_context_window || 3) : 0,
    user_can_expand: true
  };
});

return [{
  json: {
    ...searchData,
    processed_chunks: processedChunks
  }
}];

// Add learning context to results
const results = $input.first().json;
const modules = $input.item(1).json.modules || [];

return [{
  json: {
    ...results,
    learning_context: {
      related_modules: modules.map(m => ({
        module_id: m.module_id,
        module_name: m.module_name,
        relevance_note: 'This content is part of your learning path'
      })),
      progress_note: 'Reviewing this content counts toward module progress'
    }
  }
}];

// Flag as potential documentation gap
const results = $input.first().json;
const userQuestions = $input.item(1).json.questions || [];

return [{
  json: {
    ...results,
    offboarding_context: {
      user_questions_on_topic: userQuestions,
      note: 'Your expertise on this topic would be valuable in the offboarding survey',
      prompt: 'Would you like to document additional details about this?'
    }
  }
}];

// Check for override status
const results = $input.first().json;

const chunksWithOverrides = results.processed_chunks.map(chunk => {
  if (chunk.override_status === 'active') {
    // Fetch override message
    return {
      ...chunk,
      has_override: true,
      override_note: 'This content has been updated by a recent directive'
    };
  }
  return chunk;
});

return [{
  json: {
    ...results,
    processed_chunks: chunksWithOverrides
  }
}];

// Format final search response
const results = $input.first().json;
const similarQA = $input.item(1).json.qa_pairs || [];

const formattedResults = results.processed_chunks.map(chunk => ({
  chunk_id: chunk.chunk_id,
  content: chunk.content,
  standalone_score: chunk.standalone_score,
  needs_context: chunk.needs_context,
  context_available: chunk.needs_context ? {
    requires_from: chunk.requires_context_from,
    provides_to: chunk.provides_context_to,
    action: 'Click to expand context'
  } : null,
  override_info: chunk.has_override ? {
    status: 'overridden',
    message: chunk.override_note,
    view_directive: true
  } : null,
  document_info: {
    document_id: chunk.document_id,
    currency_status: chunk.currency_status,
    version: chunk.version
  }
}));

return [{
  json: {
    query: results.query,
    results: formattedResults,
    similar_qa: similarQA.map(qa => ({
      question: qa.content,
      answer: qa.answer,
      similarity: qa.similarity_score
    })),
    learning_context: results.learning_context || null,
    offboarding_context: results.offboarding_context || null,
    result_count: formattedResults.length
  }
}];

// Assemble context window
const primaryChunk = $input.first().json;
const contextChunks = $input.item(1).json.chunks || [];

// Order chunks logically
const orderedChunks = [
  ...contextChunks.filter(c => c.chunk_index < primaryChunk.chunk_index).sort((a, b) => a.chunk_index - b.chunk_index),
  primaryChunk,
  ...contextChunks.filter(c => c.chunk_index > primaryChunk.chunk_index).sort((a, b) => a.chunk_index - b.chunk_index)
];

return [{
  json: {
    primary_chunk_id: primaryChunk.chunk_id,
    context_window: orderedChunks.map(c => ({
      chunk_id: c.chunk_id,
      content: c.content,
      is_primary: c.chunk_id === primaryChunk.chunk_id,
      chunk_type: c.chunk_type,
      chunk_index: c.chunk_index
    })),
    assembly_note: 'Context assembled from related chunks for complete understanding'
  }
}];

// Aggregate all sources for baseline generation
